class Solution:

	def longestIncreasingPath(self, matrix, n, m):

		def dfs(matrix, dummy, i, j, n, m):
			if dummy[i][j] != 0:
				return dummy[i][j]
			dx = [0, 0, 1, -1]
			dy = [1, -1, 0, 0]
			res = 1
			for k in range(4):
				p = i + dx[k]
				q = j + dy[k]
				if p >= 0 and p < n and (q >= 0) and (q < m) and (matrix[i][j] < matrix[p][q]):
					res = max(res, 1 + dfs(matrix, dummy, p, q, n, m))
			dummy[i][j] = res
			return res
		dummy = [[0] * m for i in range(n)]
		maxi = 0
		for i in range(n):
			for j in range(m):
				maxi = max(maxi, dfs(matrix, dummy, i, j, n, m))
		return maxi
